from itertools import groupby


def squash(s: str) -> str:
    parts = []
    for c, group in groupby(s):
        count = sum(1 for _ in group)
        esc = f"\\{c}" if c == "\\" or "0" <= c <= "9" else c
        if count >= 3:
            parts.append(f"{count}{esc}")
        else:
            parts.append(esc * count)
    return "".join(parts)
